mapper.select:
SELECT l.id, l.card_id, l.card_no, l.user_id, l.user_name,
       l.direction, l.gate_location, l.building_id,
       l.access_time, l.access_status, l.deny_reason
FROM access_log l


        AND l.card_no LIKE CONCAT('%', #{cardNo}, '%')


        AND l.user_name LIKE CONCAT('%', #{userName}, '%')


        AND l.direction = #{direction}


        AND l.access_status = #{accessStatus}


        AND l.building_id = #{buildingId}


ORDER BY l.access_time DESC
